"""
pytotext_assets.py

Embedded binary assets for PyToText.
Contains Base64 encoded logo to ensure the application icon is always preserved
even if external files on disk are deleted or modified.
"""

import base64
from pathlib import Path
from typing import Optional

# Embedded Logo.png binary as Base64 string
LOGO_PNG_BASE64 = ""


def get_logo_bytes() -> bytes:
    """Return the decoded raw bytes of the logo image."""
    return base64.b64decode(LOGO_PNG_BASE64)


def ensure_logo_file(target_path: Optional[Path] = None) -> Path:
    """
    Ensure Logo.png exists at the target path (defaults to project root).
    If it is missing, it will be automatically recreated from embedded assets.
    """
    if target_path is None:
        target_path = Path(__file__).parent / "Logo.png"
    else:
        target_path = Path(target_path)

    if not target_path.exists():
        try:
            target_path.write_bytes(get_logo_bytes())
            print(f"[Asset Restorer] Recreated missing {target_path.name} from embedded asset.")
        except Exception as e:
            print(f"[Asset Restorer] Warning: Could not write {target_path}: {e}")
    return target_path


def get_app_icon():
    """
    Construct and return a PyQt6 QIcon directly from memory.
    Falls back gracefully if PyQt6 is not installed.
    """
    try:
        from PyQt6.QtCore import QByteArray
        from PyQt6.QtGui import QIcon, QPixmap

        pixmap = QPixmap()
        raw_bytes = get_logo_bytes()
        byte_array = QByteArray(raw_bytes)
        if pixmap.loadFromData(byte_array, "PNG"):
            return QIcon(pixmap)
    except Exception as e:
        pass
    return None


def get_logo_pixmap(width: int = 0, height: int = 0):
    """
    Return a QPixmap of the logo, optionally scaled smoothly to (width, height).
    """
    try:
        from PyQt6.QtCore import QByteArray, Qt
        from PyQt6.QtGui import QPixmap

        pixmap = QPixmap()
        raw_bytes = get_logo_bytes()
        byte_array = QByteArray(raw_bytes)
        if pixmap.loadFromData(byte_array, "PNG"):
            if width > 0 and height > 0:
                return pixmap.scaled(
                    width,
                    height,
                    Qt.AspectRatioMode.KeepAspectRatio,
                    Qt.TransformationMode.SmoothTransformation,
                )
            return pixmap
    except Exception as e:
        pass
    return None
